const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const requestId = input.request_id || `req_${Date.now()}_${Math.floor(Math.random() * 100000)}`;
const patientId = input.patient_id || input.paciente_id || null;
const therapistId = input.therapist_id || input.fisioterapeuta_id || input.professional_id || null;
const symptomsText = String(input.symptoms_text || input.symptoms || input.message_text || input.text || '').trim();
const systemPrompt = String(input.system_prompt || input.prompt || input.agent_prompt || '').trim();
const promptVersion = input.prompt_version || null;

const rawCandidates = Array.isArray(input.candidate_exercises)
  ? input.candidate_exercises
  : Array.isArray(input.catalog)
    ? input.catalog
    : [];

const candidateExercises = rawCandidates
  .map((item) => ({
    exercise_id: item.exercise_id || item.id || null,
    name: item.name || item.nombre || '',
    description: item.description || item.descripcion || '',
    contraindicaciones: Array.isArray(item.contraindications)
      ? item.contraindications
      : Array.isArray(item.contraindicaciones)
        ? item.contraindicaciones
        : [],
    zona_corporal: item.zona_corporal || item.body_area || null,
    nivel: item.nivel || item.level || null,
    object_key: item.object_key || null
  }))
  .filter((item) => item.exercise_id);

const redFlagContext = Array.isArray(input.red_flag_context) ? input.red_flag_context : [];

return [{
  json: {
    request_id: requestId,
    prompt_version: promptVersion,
    system_prompt: systemPrompt,
    patient_id: patientId,
    therapist_id: therapistId,
    symptoms_text: symptomsText,
    red_flag_context: redFlagContext,
    candidate_exercises: candidateExercises,
    candidate_count: candidateExercises.length,
    channel: input.channel || input.source || 'n8n_webhook'
  }
}];

const input = $json || {};
const statusCode = Number(input.statusCode || input.code || 0);
const raw = input.recommendation || input;

const selected = Array.isArray(raw.selected_exercises) ? raw.selected_exercises : [];
const normalizedSelected = selected
  .map((item, idx) => ({
    exercise_id: item.exercise_id || item.id || null,
    name: item.name || item.nombre || null,
    description: item.description || item.descripcion || '',
    zona_corporal: item.zona_corporal || item.body_area || null,
    procedimiento: item.procedimiento || item.procedure || item.instructions || null,
    series: item.series ?? null,
    repeticiones: item.repeticiones ?? null,
    duracion_segundos: item.duracion_segundos ?? null,
    frecuencia: item.frecuencia || item.frequency || null,
    effort_level: item.effort_level || item.effort || null,
    why: item.why || item.reason || '',
    expected_sensation: item.expected_sensation || null,
    common_mistakes: Array.isArray(item.common_mistakes) ? item.common_mistakes : [],
    cautions: Array.isArray(item.cautions) ? item.cautions : [],
    stop_if: item.stop_if || null,
    progression_tip: item.progression_tip || null,
    object_key: item.object_key || null,
    signed_url_ttl_seconds: 1200,
    rank: idx + 1
  }))
  .filter((item) => item.exercise_id);

const hasEngineError = statusCode >= 400;
let status = 'generated';
if (hasEngineError) {
  status = 'error';
} else if (!normalizedSelected.length) {
  status = 'needs_review';
}

const fallbackPatientMessage = normalizedSelected.length
  ? 'He generado una propuesta inicial de ejercicios para revision clinica.'
  : 'Necesito mas informacion para recomendar ejercicios de forma segura.';

return [{
  json: {
    request_id: raw.request_id || input.request_id || null,
    prompt_version: raw.prompt_version || input.prompt_version || null,
    status,
    recommendation_id: raw.recommendation_id || null,
    symptom_summary: raw.symptom_summary || '',
    clinical_interpretation: raw.clinical_interpretation || '',
    main_goal: raw.main_goal || '',
    patient_cover_message: raw.patient_cover_message || '',
    selected_exercises: normalizedSelected,
    home_recommendations: Array.isArray(raw.home_recommendations) ? raw.home_recommendations : [],
    message_to_patient_es: raw.message_to_patient_es || fallbackPatientMessage,
    message_to_therapist_es: raw.message_to_therapist_es || (hasEngineError ? 'Error del motor de recomendacion' : ''),
    follow_up_focus: raw.follow_up_focus || '',
    estimated_adherence_difficulty: raw.estimated_adherence_difficulty || '',
    red_flags_present: !!raw.red_flags_present,
    red_flags_items: Array.isArray(raw.red_flags_items) ? raw.red_flags_items : [],
    selection_rationale: raw.selection_rationale || '',
    escalation_recommend_medical_attention: !!raw.escalation_recommend_medical_attention,
    escalation_reason: raw.escalation_reason || '',
    engine_status_code: statusCode || null
  }
}];

return [{
  json: {
    request_id: $json.request_id || null,
    status: 'error',
    recommendation_id: null,
    selected_exercises: [],
    message_to_patient_es: 'No pude generar la recomendacion porque faltan datos minimos (patient_id, symptoms_text o candidate_exercises).',
    message_to_therapist_es: 'Entrada invalida para W2.',
    red_flags_present: false,
    red_flags_items: [],
    selection_rationale: '',
    escalation_recommend_medical_attention: false,
    escalation_reason: 'missing_required_input'
  }
}];
